    excluded: ['Обеды и ужины', 'Личные расходы'],
    itinerary: [
      { day: 1, title: 'Бархан Сарыкум и древний Дербент', description: 'Первый день сразу задаёт масштаб — крупнейший песчаный бархан в Европе и один из древнейших городов мира. Ночной переезд. Утром — бархан Сарыкум: настоящая песчаная гора высотой более 250 м на фоне зелёных предгорий, контраст, который невозможно представить, пока не увидишь. Далее — Дербент, которому более двух тысячелетий. Цитадель Нарын-Кала (ЮНЕСКО) — крепость, которую строили, перестраивали и осаждали персы, арабы, монголы и Тамерлан; с её стен видно черепичные крыши старого города и Каспий до горизонта. Внизу — лабиринт средневековых магалов, Джума-мечеть 733 года — одна из старейших в мире, и дворы, увитые виноградом. На берегу моря — советский экраноплан «Лунь», превращённый в музей. Размещение в Махачкале.', images: ['https://images.unsplash.com/photo-1635692326243-11668510acbe?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1697396001552-53aaa4089de8?w=800&h=600&fit=crop'] },
      { day: 2, title: 'Гамсутль и подземный водопад', description: 'Самый активный день маршрута — горный Дагестан, заброшенные аулы и водопад внутри пещеры. Гамсутль — «дагестанский Мачу-Пикчу»: каменные дома сливаются со скальной вершиной, последний житель покинул аул в 2015 году. Пеший подъём по тропе через луга занимает час-полтора, зато сверху — головокружительная панорама ущелий. По пути — аул Чох, один из древнейших поселений Кавказа с живописной террасной застройкой. Далее — Салтинский водопад: редкий подземный водопад — вода падает сквозь провал в скальном своде пещеры, и когда солнце проникает внутрь, стены окрашиваются радужными бликами. Возвращение в Махачкалу к вечеру.', images: ['https://images.unsplash.com/photo-1670168630873-000f83e5dfe8?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1652808109650-9370ddaaddaa?w=800&h=600&fit=crop'] },
      { day: 3, title: 'Сулакский каньон', description: 'Главный день тура — самый глубокий каньон в Европе — и при этом доступен без специальной подготовки. Ранний выезд к Сулакскому каньону (до 1 920 м — самый глубокий в Европе). Смотровые площадки в посёлке Дубки — река Сулак внизу как тонкая бирюзовая лента, масштаб невозможно передать на фото. Спуск к воде и прогулка на катере по каньону: бирюзовая вода невероятного цвета, отвесные скалы высотой с полкилометра по обе стороны — масштаб, который не передать словами. Обед с видом на каньон. Возвращение в Махачкалу, вечерняя прогулка по набережной Каспия. Ужин — дагестанская кухня: хинкал, чуду, урбеч — блюда, ради которых стоит приехать отдельно.', images: ['https://images.unsplash.com/photo-1634715114208-9aadcc5fdc20?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1570614738755-ed5d44865d20?w=800&h=600&fit=crop'] },
      { day: 4, title: 'Махачкала и возвращение', description: 'Спокойное завершение — столица Дагестана без спешки и рынок, где можно увезти с собой вкус Кавказа. Обзорная прогулка по Махачкале: центральная Джума-мечеть — одна из крупнейших в России, вмещает 17 000 человек, внутри — мрамор и хрустальные люстры. Набережная Каспийского моря. Центральный рынок — урбеч из десятков видов орехов и семян, сушёные фрукты, горный мёд, дагестанские сладости. Свободное время для покупок. Выезд домой, прибытие поздно вечером.', images: ['https://images.unsplash.com/photo-1617573543793-1b13d0a3f75c?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1634715107433-d9e3403f5bc8?w=800&h=600&fit=crop'] },
    ],
    gallery: ['https://images.unsplash.com/photo-1697394921138-1247d8bf32bf?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1554197913-f5998d997f42?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1634715109536-cb9a1bb02cec?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1673446319197-35ba29be3d22?w=800&h=600&fit=crop', 'https://images.unsplash.com/photo-1635692326243-11668510acbe?w=800&h=600&fit=crop'],
