    destinations: ['Чечня', 'Северная Осетия'],
    shortDescription: 'Два региона Кавказа за одну поездку: Грозный, Аргунское ущелье, Даргавс и Цейский ледник.',
    fullDescription: 'Две республики — два характера Кавказа в одной поездке. Чечня поражает масштабом: отстроенный с нуля Грозный с небоскрёбами и мечетью мирового уровня, горные ущелья с боевыми башнями. Осетия завораживает глубиной: средневековые некрополи, ледники, термальные источники и одна из старейших христианских традиций на Кавказе.\n\nГрозный и Аргунское ущелье — мечеть «Сердце Чечни» с интерьерами, расписанными вручную, Грозный-Сити со смотровой, вечерний город в подсветке. Ущелье вдоль реки Чанты-Аргун — Ушкалойские башни-близнецы в скале, Нихалойские водопады, замковый комплекс Пхакоч.\n\nВладикавказ — столица Осетии с видом на Столовую гору. Проспект Мира — одна из красивейших улиц Кавказа, суннитская мечеть на берегу Терека. Мастер-класс по осетинским пирогам — три пирога с тремя начинками, которые вы готовите сами.\n\nГорная Осетия — Даргавс, «Город мёртвых», с башенными склепами XIV–XVIII веков в горной долине. Цейское ущелье с ледником и альпийскими лугами. Кармадонское ущелье — грозное и впечатляющее. Мидаграбинские водопады — одни из самых высоких в Европе. Горячие термальные источники для отдыха после дня в горах.',
