    fullDescription: 'Весь Крым за пять дней — от императорских дворцов Южного берега до пещерных городов и военных бухт Севастополя. Маршрут построен так, чтобы за одну поездку вы увидели все грани полуострова: и парадный курортный Крым, и горный, и военно-исторический.\n\nЮжный берег — Ливадийский дворец, где проходила Ялтинская конференция, Воронцовский дворец у подножия Ай-Петри с английским парком и львиной террасой, замок «Ласточкино гнездо» на скале над морем. Ялтинская набережная, Массандровский дворец Александра III в окружении виноградников. Подъём на Ай-Петри — с канатной дороги открывается панорама побережья от Ялты до Алушты.\n\nСевастополь — город-крепость с 2500-летней историей. Графская пристань, площадь Нахимова, Владимирский собор — усыпальница адмиралов. Балаклава — секретная база подводных лодок в скале и живописная бухта. Бахчисарай — Ханский дворец, Свято-Успенский монастырь в скале и пещерный город Чуфут-Кале.\n\nКаждый день — новый город и новая тема. Проживание в гостиницах на побережье, завтраки включены. Маршрут подходит для любого возраста и не требует физической подготовки.',
