    fullDescription: 'Два дня — два совершенно разных мира. Ультрасовременный Грозный, отстроенный с нуля, и горная Чечня с боевыми башнями, водопадами и ущельями, где дорога идёт по краю скалы над рекой. Контраст, который запоминается надолго.\n\nГрозный — город, который поражает масштабом восстановления. Мечеть «Сердце Чечни» — одна из крупнейших в Европе, с четырьмя 63-метровыми минаретами и интерьером, расписанным турецкими мастерами. Комплекс «Грозный-Сити» со смотровой площадкой, Цветочный парк, Храм Архангела Михаила 1868 года — рядом с небоскрёбами. Вечерний Грозный в подсветке — зрелище, ради которого стоит задержаться.\n\nАргунское ущелье — дорога вдоль реки Чанты-Аргун, зажатой между скалами. Ушкалойские башни-близнецы — средневековые сторожевые башни, врезанные прямо в скалу. Нихалойские водопады — каскад из 12 водопадов в горном ущелье. Замковый комплекс Пхакоч с краеведческим музеем — оружие, предметы быта, история горного народа.\n\nЧеченское гостеприимство — отдельная тема: вас накормят так, что захочется вернуться. Жижиг-галнаш, чепалгаш, домашний сыр и горный мёд.',
