    shortDescription: 'Кремль с Оружейной палатой, Красная площадь, Третьяковская галерея, смотровая Москва-Сити и теплоход по Москве-реке — 4 дня в ритме столицы.',
    fullDescription: 'Москва не помещается ни в один путеводитель — и не поместится в один день. Но за четыре дня можно увидеть весь её диапазон: от Кремля, где короновали царей, до смотровой площадки на 89-м этаже Москва-Сити, откуда город лежит как на ладони. Оружейная палата, Красная площадь, Третьяковка, Зарядье, теплоход по Москве-реке — всё главное, без суеты и без компромиссов.\n\nПрограмма начинается с обзорной автобусной экскурсии: Воробьёвы горы с панорамой на город, Поклонная гора с Триумфальной аркой, Храм Христа Спасителя — один из крупнейших православных соборов мира, Новодевичий монастырь с некрополем, сталинские высотки и набережные.\n\nВторой день — сердце столицы. Красная площадь: Собор Василия Блаженного с его невероятными куполами, ГУМ с витражной крышей и фонтаном, Мавзолей Ленина, Исторический музей. Московский Кремль: Успенский собор, где венчались на царство русские цари, Архангельский собор с усыпальницами, Царь-пушка весом 40 тонн и Царь-колокол в 200 тонн. Оружейная палата — музей-сокровищница с шапкой Мономаха, тронами Ивана Грозного, царскими каретами и коронационным платьем Екатерины Великой. Вечером — парк «Зарядье» с Парящим мостом, который выступает над Москвой-рекой на 70 метров без единой опоры.\n\nТретий день — искусство и современность. Третьяковская галерея: «Троица» Рублёва, «Бурлаки на Волге» Репина, «Богатыри» Васнецова, пейзажи Левитана. После обеда — ВДНХ: павильон «Космос» с настоящим космическим кораблём «Восток», фонтан «Дружба народов» с позолоченными скульптурами 16 республик. Вечером — подъём на смотровую площадку Москва-Сити (89 этаж, высота 354 метра) и теплоходная прогулка по Москве-реке мимо подсвеченного Кремля и Храма Христа Спасителя.\n\nРазмещение в гостинице, завтраки включены. Проезд до Москвы — отдельно, менеджер поможет подобрать билеты.',
