    title: 'Казань — сокровища Татарстана',
    shortDescription: 'Казанский Кремль и мечеть Кул-Шариф, остров-град Свияжск, древний Болгар с Белой мечетью, Раифский монастырь — 4 дня на стыке культур.',
    fullDescription: 'Казань — город, где мечети соседствуют с православными соборами, а тысячелетняя история переплетается с хай-тек-архитектурой. За четыре дня вы увидите всё, ради чего сюда едут путешественники со всей России.\n\nКазанский Кремль — объект Всемирного наследия ЮНЕСКО. Белокаменные стены, за которыми — мечеть Кул-Шариф с голубыми куполами и смотровой площадкой, Благовещенский собор XVI века, построенный по указу Ивана Грозного, и знаменитая башня Сююмбике — «падающая башня» Казани высотой 58 метров, с наклоном почти 2 метра. На вершине — позолоченный полумесяц, а кованые ворота «День и ночь» у подножия украшены зодиакальными символами.\n\nОстров-град Свияжск — крепость посреди воды, основанная Иваном Грозным в 1551 году. Сюда нужно ехать ради уникальных фресок XVI века в Успенском соборе (тоже ЮНЕСКО), белоснежных монастырей и атмосферы русского острова, застывшего во времени.\n\nДревний Болгар — бывшая столица Волжской Булгарии, где до сих пор стоят руины Соборной мечети XIII века. Белая мечеть «Ак мэчет» — архитектурная жемчужина, отражающаяся в водной глади. Музей Болгарской цивилизации хранит артефакты раскопок. А в здании «Памятного знака» — самый большой печатный Коран в мире.\n\nРаифский Богородицкий монастырь на берегу тихого лесного озера — одно из самых умиротворённых мест Поволжья. Храм всех религий — удивительный архитектурный комплекс, объединяющий символы 16 мировых конфессий.\n\nМежду экскурсиями — прогулки по пешеходной улице Баумана, дегустация эчпочмаков, чак-чака и казылыка, вечерняя набережная Казанки с видом на подсвеченный Кремль. Размещение в гостинице, завтраки включены. Проезд до Казани — отдельно, менеджер поможет подобрать билеты.',
