    fullDescription: 'Западная Беларусь — это территория, где переплелись польская шляхта, литовские князья и белорусский уклад. Этот маршрут раскрывает самую европейскую часть страны.\n\nМинск — современная столица с островками истории: Троицкое предместье, ратуша, Верхний город. Лида — замок Гедимина XIV века, где проходили рыцарские турниры. Гродно — город на Немане, который называют «белорусским Краковом»: Фарный костёл с действующим алтарём XVII века, Каложская церковь XII века, замки и набережная.\n\nОрганный концерт, прогулка на теплоходе, дегустация белорусской кухни. Пять дней, чтобы влюбиться в Беларусь.',
